<section class="panel mb-4"><div class="panel-heading"><h2>Products & pack sizes</h2><div class="d-flex gap-2"><button class="btn btn-light btn-sm" wire:click="productForm"><i aria-hidden="true" class="bi bi-plus"></i> Product</button><button class="btn btn-peach btn-sm" wire:click="batchForm"><i aria-hidden="true" class="bi bi-box-seam"></i> Receive stock</button></div></div><p class="small muted">Honey pack sizes share stock by pool, measured in integer grams. Snacks use whole packaged units. Thresholds are per pool in base units.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product / stock pool</th><th>Pack size</th><th>Price</th><th>Available</th><th>Low stock threshold</th><th></th></tr></thead><tbody>@forelse($products as $p) @php($available=\Illuminate\Support\Facades\DB::table('batches')->where('stock_key',$p->stock_key)->sum(\Illuminate\Support\Facades\DB::raw('physical-reserved')))<tr><td><strong>{{ $p->name }}</strong><small class="d-block muted">{{ $p->stock_key }}</small></td><td>{{ $p->pack_quantity }} {{ $p->kind==='honey'?'g':'unit' }}</td><td>{{ $money($p->price) }}</td><td><span class="{{ $available<=$p->low_stock?'text-danger':'text-success' }}">{{ number_format($available) }} {{ $p->kind==='honey'?'g':'units' }}</span></td><td>{{ number_format($p->low_stock) }}</td><td><button class="btn btn-sm btn-light" wire:click="productForm({{ $p->id }})">Edit</button></td></tr>@empty<tr><td colspan="6"><div class="empty-state"><i aria-hidden="true" class="bi bi-flower2"></i><strong>Start with your first product.</strong><p>Add honey pack sizes or a packaged snack, then receive a batch.</p></div></td></tr>@endforelse</tbody></table></div></section>
<section class="panel mb-4"><div class="panel-heading"><h2>Stock batches</h2><span class="mini-pill">Oldest available first</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Batch / received</th><th>Stock pool</th><th>Original</th><th>Physical</th><th>Reserved</th><th>Available</th><th>Dispatched, net returns</th><th>Investment</th></tr></thead><tbody>@forelse($batches as $b)<tr><td>{{ $b->reference }}<small class="d-block muted">{{ $b->received_on }}</small></td><td>{{ $b->stock_key }}</td><td>{{ number_format($b->original_quantity) }}</td><td>{{ number_format($b->physical) }}</td><td>{{ number_format($b->reserved) }}</td><td>{{ number_format($b->physical-$b->reserved) }}</td><td>{{ number_format($b->dispatched_quantity??0) }}</td><td>{{ $money($b->purchase+$b->packaging+$b->branding+$b->other) }}</td></tr>@empty<tr><td colspan="8" class="py-4 muted">No stock batches yet.</td></tr>@endforelse</tbody></table></div>{{ $batches->links() }}</section>
<section class="panel"><h2 class="h5">Document a stock adjustment</h2><p class="small muted">Use a signed quantity in grams or whole units. Negative quantities record loss; positive quantities correct a prior loss. Receive new purchases as a new batch. Reserved stock cannot be removed.</p><form class="row g-3" wire:submit="adjust"><div class="col-md-4"><label class="form-label" for="adjust-batch">Batch</label><select id="adjust-batch" class="form-select" wire:model="adjustBatch" required><option value="0">Choose batch</option>@foreach(\Illuminate\Support\Facades\DB::table('batches')->orderByDesc('id')->get() as $b)<option value="{{ $b->id }}">{{ $b->reference }} · {{ $b->stock_key }}</option>@endforeach</select></div><div class="col-md-3"><label class="form-label" for="adjust-qty">Signed base quantity</label><input id="adjust-qty" class="form-control" type="number" wire:model="adjustQuantity" required></div><div class="col-md-5"><label class="form-label" for="adjust-reason">Reason</label><input id="adjust-reason" class="form-control" wire:model="adjustReason" minlength="5" required></div><div><button class="btn btn-sage" wire:loading.attr="disabled">Record adjustment</button></div></form><details class="mt-3"><summary>Recent adjustment history</summary>@foreach(\Illuminate\Support\Facades\DB::table('stock_adjustments as a')->join('batches as b','b.id','=','a.batch_id')->select('a.*','b.reference')->orderByDesc('a.id')->limit(30)->get() as $adjust)<p class="small mb-1">{{ $adjust->created_at }} · {{ $adjust->reference }} · {{ $adjust->quantity>0?'+':'' }}{{ $adjust->quantity }} · {{ $adjust->reason }}</p>@endforeach</details></section>
